@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<FrontPage>
@{
    Layout = "_Layout";
    ViewData["Title"] = Model.Title;
    var posts = Model.Children<BlogPost>().OrderByDescending(post => post.Date).ToList();
}
<header class="mb-10">
    <h1 class="text-4xl font-bold tracking-tight">@Model.Title</h1>
    @if (!string.IsNullOrWhiteSpace(Model.Intro))
    {
        <p class="mt-4 text-lg text-slate-600">@Model.Intro</p>
    }
</header>

<div class="mb-12 space-y-8">
    @await Html.GetBlockGridHtmlAsync(Model.Body, "blocks")
</div>

<section class="space-y-12">
    @foreach (var post in posts)
    {
        var isoDate = post.Date.ToString("yyyy-MM-dd");
        <article class="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">
            @if (post.ListingImage != null)
            {
                <a href="@post.Url()">
                    <img src="@post.ListingImage.GetCropUrl(width: 800, height: 450)" alt="@post.Title" loading="lazy" class="h-64 w-full object-cover" />
                </a>
            }
            <div class="p-6">
                <p class="text-sm text-slate-500"><time datetime="@isoDate">@post.Date.ToString("d MMMM yyyy")</time></p>
                <h2 class="mt-2 text-2xl font-semibold tracking-tight">
                    <a href="@post.Url()" class="hover:underline">@post.Title</a>
                </h2>
                <p class="mt-3 text-slate-600">@post.Excerpt</p>
                <a href="@post.Url()" class="mt-4 inline-block text-sm font-medium text-indigo-700 hover:underline">Read the post</a>
            </div>
        </article>
    }
</section>

